#!/usr/bin/env python3
"""Source-checked additions to §§10–19. Writes only new draft detail cards and coverage."""
import copy,json,math
from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parents[2]; COURSE=ROOT/'stereo-course/merzlyak-10-base'; OUT=COURSE/'lessons'
INDEX=json.loads((COURSE/'source-index.json').read_text()); OVER={n:json.loads((OUT/f'theory-{n:02}.json').read_text()) for n in range(10,20)}
CARDS=[]
def chain(names):return [[names[i],names[(i+1)%len(names)]]for i in range(len(names))]
def scene(points,edges,faces,views,caption,labels=None):
 return {'type':'scene3d','caption':caption+' Плоскости и прямые продолжаются за пределы показанных фрагментов; координаты служат иллюстрацией, а доказательство относится ко всем указанным фигурам.', 'model':{'points':{k:[float(x) for x in v]for k,v in points.items()},'edges':edges,'faces':faces,'labelNames':labels if labels is not None else list(points)[:8],'views':{'neutral':{'label':'Исходные данные'},**views}}}
def v(label,segments=None,polygon=None,points=None):
 d={'label':label}
 if segments:d['segments']=segments
 if polygon:d['polygon']=polygon
 if points:d['points']=points
 return d
def box(u=(3,0,0),w=(0,3,0),h=(0,0,3)):
 u,w,h=map(np.array,[u,w,h]);p={'A':np.zeros(3),'B':u,'C':u+w,'D':w}
 p.update({k+'1':x+h for k,x in list(p.items())});faces=[['A','B','C','D'],['A1','B1','C1','D1']]+[[a,b,b+'1',a+'1']for a,b in chain(['A','B','C','D'])];edges=chain(['A','B','C','D'])+chain(['A1','B1','C1','D1'])+[[a,a+'1']for a in 'ABCD'];return p,edges,faces

def card(n,k,part,title,statement,pages,vis,steps,hint,source_units):
 src={'bookId':'merzlyak-2022-10-base','collection':'theory','point':str(n),'subpart':part,'chapter':OVER[n]['source']['chapter'],'printedPages':[p-1 for p in pages],'pdfPages':pages}
 ss=[]
 for i,(heading,explanation,view,reason) in enumerate(steps,1):
  assert view in vis['model']['views'],(n,k,view)
  ss.append({'id':f'step-{i}','title':heading,'prompt':heading,'explanation':explanation,'justifications':[{'kind':'theorem','text':reason}],'view':view})
 d={'schemaVersion':1,'revision':1,'id':f'merz-theory-{n:02}-detail-{k:02}','kind':'theory','title':f'§ {n}. {title}','status':'draft','source':src,'statement':{'text':statement,'goal':'Обосновать каждый переход и отличить общий вывод от иллюстрации.'},'visualization':vis,'help':[{'id':'help-1','question':'С чего начать?','text':hint,'children':[{'id':'help-2','question':'Как проверить полноту рассуждения?','text':'Назови все условия, нужные выбранной теореме. Проверь принадлежность точек и прямых плоскостям, затем отдельно сформулируй вывод для произвольного случая.','children':[]}]}],'steps':ss,'answer':{'mode':'manual','prompt':'Запиши собственное доказательство или решение. Текст сохраняется для обсуждения с преподавателем; автоматической проверки правильности нет.'},'review':{'source':'pending','mathematics':'pending','pedagogy':'pending'}}
 fn=f'theory-{n:02}-detail-{k:02}.json';(OUT/fn).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');CARDS.append({'paragraph':n,'part':part,'lessonId':d['id'],'lessonFile':f'stereo-course/merzlyak-10-base/lessons/{fn}','sourcePdfPages':pages,'sourceUnits':source_units,'sourceReading':'visually_checked','authoringStatus':'draft_pending_independent_review'})

# §10: two concrete embedded examples.
p,e,f=box();vis=scene(p,e,f,{'projection':v('Верхнее основание проектируется на нижнее',[['A1','A'],['B1','B'],['C1','C'],['D1','D']],['A','B','C','D']),'distance':v('AD — общий перпендикуляр AA₁ и CD',[['A','A1'],['C','D'],['A','D']])},'Куб: ортогональная проекция основания и расстояние между скрещивающимися рёбрами.')
card(10,1,'примеры: проекция основания и расстояние в кубе','Два примера на кубе','В прямоугольном параллелепипеде объясните ортогональное проектирование верхнего основания на нижнее. В кубе найдите расстояние между прямыми AA₁ и CD через ребро a.',[99,102],vis,[('Почему проекция верхнего основания совпадает с нижним?','Все боковые рёбра прямоугольного параллелепипеда перпендикулярны основаниям. Поэтому A₁→A, B₁→B, C₁→C, D₁→D. Каждая точка верхнего прямоугольника проектируется на соответствующую точку нижнего; получаем весь ABCD.','projection','Ортогональное проектирование и равенство оснований прямоугольного параллелепипеда.'),('Почему AA₁ и CD скрещиваются?','AA₁ пересекает плоскость ABCD в A, причём A не лежит на CD. По признаку скрещивающихся прямых AA₁ и CD не лежат в одной плоскости.','distance','Признак скрещивающихся прямых, §4.'),('Какой отрезок измеряет расстояние?','Концы AD лежат соответственно на AA₁ и CD. В кубе AD⊥AA₁ и AD⊥CD. Следовательно, AD — общий перпендикуляр; искомое расстояние равно AD=a. Тот же результат даёт расстояние между параллельными гранями ABB₁A₁ и DCC₁D₁.','distance','Определение общего перпендикуляра и расстояния между скрещивающимися прямыми.')],'Для проекции проверь направление боковых рёбер. Для расстояния найди отрезок с концами на обеих прямых и проверь две перпендикулярности.',['example-projection-parallelepiped-base','example-cube-skew-distance'])
# Circumcenter: a scalene cyclic triangle, not a regular-only argument.
p={'O':[0,0,0],'M':[0,0,2],'A':[3,0,0],'B':[-1.8,2.4,0],'C':[-1.8,-2.4,0]};vis=scene(p,chain(['A','B','C'])+[['M',x]for x in ['O','A','B','C']]+[['O',x]for x in 'ABC'],[['A','B','C']],{'heights':v('Общий катет MO',[['M','O'],['M','A'],['M','B'],['M','C']]),'radii':v('Равные радиусы OA, OB, OC',[['O','A'],['O','B'],['O','C']])},'Точка M равноудалена от вершин треугольника; O — её ортогональная проекция.')
card(10,2,'ключевая задача 1: центр описанной окружности','Равноудалённость от вершин','Точка M вне плоскости многоугольника равноудалена от всех его вершин. Докажите, что её ортогональная проекция O — центр описанной около многоугольника окружности.',[100],vis,[('Как получить прямоугольные треугольники?','Опустим MO на плоскость основания. Для каждой вершины V отрезок OV лежит в этой плоскости, поэтому MO⊥OV. O не может совпасть с вершиной: тогда расстояние от M до неё было бы h, а до любой другой вершины — больше h, вопреки условию. Поэтому треугольник MOV невырожденный и прямоугольный при O.','heights','Определение перпендикулярности прямой и плоскости.'),('Почему расстояния от O до вершин равны?','Пусть общее расстояние от M до вершин равно l, а MO=h. По теореме Пифагора для каждой вершины V: OV²=l²−h². Правая часть одна и та же, значит, OA=OB=OC=…=R.','radii','Теорема Пифагора применена с общим катетом MO.'),('Почему это именно описанная окружность?','Все вершины лежат в одной плоскости на расстоянии R от O, поэтому принадлежат окружности с центром O и радиусом R. Радиус положителен: у многоугольника несколько различных вершин. Полученная окружность описана около многоугольника. O может оказаться вне многоугольника; доказательство этого не исключает.','radii','Определение окружности и описанной окружности.')],'Сравни прямоугольные треугольники с общим перпендикуляром. Равенство гипотенуз должно дать равенство оставшихся катетов.',['key-task-10-1'])
# Parallel line and plane, then parallel planes; same concrete orthogonal prism.
p={'A':[-2,-1,2],'B':[2,-1,2],'C':[0,2,2],'A1':[-2,-1,0],'B1':[2,-1,0],'C1':[0,2,0]};e=chain(['A','B','C'])+chain(['A1','B1','C1'])+[[x,x+'1']for x in 'ABC'];vis=scene(p,e,[['A','B','C'],['A1','B1','C1']],{'rectangle':v('ABB₁A₁ — прямоугольник',[['A','A1'],['B','B1']],['A','B','B1','A1']),'planes':v('Произвольные точки одной параллельной плоскости',[['A','A1'],['B','B1'],['C','C1']],['A','B','C'])},'Прямая AB и плоскость ABC параллельны плоскости A₁B₁C₁.')
card(10,3,'ключевые задачи 2–3: равноудалённость параллельных объектов','Почему расстояние не зависит от точки','Докажите: 1) все точки прямой, параллельной плоскости, равноудалены от неё; 2) все точки одной из двух параллельных плоскостей равноудалены от другой.',[101,102],vis,[('Что строим для двух точек прямой?','Возьмём любые различные A,B на прямой a∥α и опустим AA₁, BB₁ на α. Эти перпендикуляры параллельны. Их основания различны: иначе единственность перпендикуляра дала бы A,B на одной нормали, и a пересекала бы α.','rectangle','Теоремы 9.3–9.4 о перпендикулярах к плоскости.'),('Почему получаем равные перпендикуляры?','Параллельные AA₁ и BB₁ задают плоскость. Она содержит AB и пересекает α по A₁B₁. Так как AB∥α, имеем AB∥A₁B₁. Четырёхугольник ABB₁A₁ — параллелограмм с прямым углом, значит, прямоугольник. Отсюда AA₁=BB₁.','rectangle','Теорема 5.2 и свойство противоположных сторон параллелограмма.'),('Как перейти от прямой к двум плоскостям?','Пусть β∥α, а A,B — любые две точки β. При A≠B прямая AB лежит в β и не имеет общих точек с α, то есть AB∥α. Уже доказанное утверждение даёт одинаковые расстояния от A и B до α. При A=B равенство очевидно.','planes','Параллельные плоскости не имеют общих точек; ключевая задача 2.'),('Почему определения расстояний однозначны?','Поэтому для прямой, параллельной плоскости, можно брать любую её точку; для двух параллельных плоскостей — любую точку одной из них. Все полученные длины равны. Перпендикуляр между параллельными плоскостями перпендикулярен обеим, поэтому выбор первой плоскости также не меняет расстояние.','planes','Равноудалённость и общий перпендикуляр параллельных плоскостей.')],'Сначала докажи утверждение для двух произвольных точек одной прямой. Во второй задаче соедини две точки первой плоскости.',['key-task-10-2','key-task-10-3'])
p={'L':[-2,0,0],'R':[2,0,0],'A':[-1.2,-2,2],'B':[1.2,2,2],'A1':[-1.2,-2,0],'B1':[1.2,2,0],'M':[0,0,0],'N':[0,0,2],'T':[0,2.5,0]};vis=scene(p,[['L','R'],['A','B'],['A1','B1'],['A','A1'],['B','B1'],['M','N']],[['L','R','T']],{'project':v('Проекция b на плоскость через a',[['A','A1'],['B','B1'],['A1','B1'],['L','R']]),'common':v('MN — общий перпендикуляр',[['M','N'],['L','R'],['A','B']],None,['M','N'])},'a=LR и b=AB скрещиваются. Их направления не обязаны быть взаимно перпендикулярны.',labels=['L','R','A','B','A1','B1','M','N'])
card(10,4,'ключевая задача 4: существование общего перпендикуляра','Как построить общий перпендикуляр','Для любых двух скрещивающихся прямых a,b докажите существование отрезка с концами на них, перпендикулярного обеим прямым. Объясните, почему его длина равна расстоянию между прямыми.',[102,103],vis,[('Как выбрать вспомогательную плоскость?','Через a проведём плоскость α, параллельную b: возьмём через точку a прямую b′∥b и плоскость двух пересекающихся прямых a,b′. Прямая b не лежит в α, иначе a,b были бы компланарны; по признаку параллельности b∥α.','project','Через две пересекающиеся прямые проходит плоскость; признак параллельности прямой и плоскости.'),('Почему проекция b пересекает a?','Опустим AA₁ и BB₁ из двух различных точек b на α. Прямоугольник ABB₁A₁ даёт A₁B₁∥b. Если бы A₁B₁ была параллельна a или совпадала с ней, направления a,b были бы параллельны, что невозможно для скрещивающихся прямых. Поэтому в α прямые a и A₁B₁ пересекаются в точке M.','project','Ключевая задача 2; классификация двух прямых одной плоскости.'),('Где взять второй конец отрезка?','В плоскости ABB₁A₁ проведём через M прямую, параллельную AA₁. Она пересечёт AB в N, поскольку в прямоугольнике направления AA₁ и AB различны. Тогда MN⊥α и N∈b, M∈a. Из MN⊥α следует MN⊥a. Кроме того, MN⊥AB, то есть MN⊥b.','common','Прямая, параллельная перпендикуляру к плоскости, тоже перпендикулярна плоскости.'),('Почему длина MN — искомое расстояние?','Отрезок MN перпендикулярен α и соединяет точку N прямой b с α, следовательно, MN=d(b,α). По определению расстояния между скрещивающимися прямыми это d(a,b). Тем самым одновременно построен общий перпендикуляр и доказана формула расстояния.','common','Определения расстояния до плоскости и расстояния между скрещивающимися прямыми.')],'Спроектируй одну прямую на плоскость, содержащую вторую и параллельную первой. Отдельно обоснуй, что две прямые в плоскости обязательно пересекаются.',['key-task-10-4','common-perpendicular-distance-property'])

# §11: convex-polygon incircle criterion.
def incircle_scene(apex='M'):
 p={'A':[0,0,0],'B':[4,0,0],'C':[0,3,0],'O':[1,1,0],apex:[1,1,2],'N':[1,0,0],'K':[1.6,1.8,0],'E':[0,1,0]}
 ed=chain(['A','B','C'])+[[apex,x]for x in ['O','N','K','E']]+[['O',x]for x in ['N','K','E']]
 return p,ed,[['A','B','C']]
p,e,f=incircle_scene();vis=scene(p,e,f,{'feet':v('Перпендикуляры к сторонам из O',[['O','N'],['O','K'],['O','E']]),'inclines':v('Расстояния от M до прямых сторон',[['M','N'],['M','K'],['M','E']]),'triangle':v('Общий катет MO',None,['M','O','N'])},'Скаленый треугольник; O расположен внутри. Пример не требует правильного основания.')
card(11,1,'ключевая задача: центр вписанной окружности','Равноудалённость от прямых сторон','M вне плоскости выпуклого многоугольника равноудалена от всех прямых, содержащих его стороны. Проекция O точки M принадлежит многоугольнику. Докажите, что O — центр вписанной окружности.',[109],vis,[('Какие перпендикуляры нужны?','Из O опустим ON,OK,OE на прямые AB,BC,CA; для n-угольника так поступим с каждой стороной. По теореме о трёх перпендикулярах MN⊥AB, MK⊥BC, ME⊥CA, поэтому именно эти отрезки измеряют расстояния от M до прямых сторон.','feet','Теорема 11.1 о трёх перпендикулярах.'),('Как получить равные радиусы?','По условию MN=MK=ME=…=l. В прямоугольных треугольниках MON,MOK,MOE общий катет MO=h. Следовательно, ON²=OK²=OE²=…=l²−h². Все расстояния от O до прямых сторон равны одному r.','triangle','Теорема Пифагора.'),('Почему принадлежность O многоугольнику существенна?','Радиус r не может быть нулём: тогда все прямые сторон проходили бы через O, что невозможно для невырожденного выпуклого многоугольника. Значит, O лежит строго внутри, а круг радиуса r целиком лежит во всех внутренних полуплоскостях его сторон и потому внутри многоугольника.','feet','Выпуклый многоугольник — пересечение внутренних полуплоскостей сторон.'),('Почему окружность касается самих сторон?','Окружность касается каждой прямой стороны в основании соответствующего перпендикуляра. Весь круг лежит внутри многоугольника, поэтому эти точки касания принадлежат сторонам, а не их продолжениям. Это вписанная окружность с центром O. Без условия о положении O могла бы получиться вневписанная окружность.','inclines','Определение вписанной окружности.')],'Сначала докажи, что отрезки от M до оснований перпендикуляров из O действительно перпендикулярны прямым сторон. Не забудь использовать условие O внутри многоугольника.',['key-task-11'])
# §12: exact cube example and equal-angle key task.
p,e,f=box();vis=scene(p,e+[['A','B1']],f,{'angle':v('∠B₁AB — угол AB₁ с основанием',[['A','B1'],['A','B'],['B','B1']],['A','B','B1'])},'Диагональ квадратной боковой грани куба и её проекция.')
card(12,1,'пример: диагональ грани куба','Почему здесь угол 45°?','В кубе ABCDA₁B₁C₁D₁ найдите угол между диагональю AB₁ боковой грани и плоскостью ABC.',[114],vis,[('Что проектируется во что?','B₁B перпендикулярен основанию, поэтому B₁ проектируется в B. Точка A уже лежит в плоскости основания. Следовательно, проекция AB₁ — AB.','angle','Ортогональное проектирование.'),('Где расположен искомый угол?','По определению угол между прямой AB₁ и плоскостью ABC равен острому углу B₁AB. Он расположен при общей точке прямой и её проекции, то есть при A.','angle','Определение угла между прямой и плоскостью.'),('Почему угол равен 45°?','В прямоугольном треугольнике ABB₁ катеты AB и BB₁ равны как рёбра куба. Острые углы равны и в сумме дают 90°, поэтому ∠B₁AB=45°. Угол отрезка с плоскостью по определению совпадает с углом содержащей его прямой.','angle','Свойства равнобедренного прямоугольного треугольника.')],'Определи проекции обоих концов диагонали. Затем используй равенство рёбер куба.',['embedded-example-12.3','definition-segment-plane-angle'])
p={'M':[0,0,2],'O':[0,0,0],'A':[3,0,0],'B':[0,3,0],'C':[-1,-1,0]};vis=scene(p,[['M','O'],['M','A'],['M','B'],['O','A'],['O','B']],[['A','B','C']],{'first':v('Первый прямоугольный треугольник',None,['M','O','A']),'second':v('Второй прямоугольный треугольник',None,['M','O','B']),'radii':v('Равные проекции',[['O','A'],['O','B']])},'Две наклонные из одной точки образуют равные углы с плоскостью.')
card(12,2,'ключевая задача: равные углы наклонных','Равные углы дают равные проекции','Из точки M вне плоскости проведены наклонные MA,MB, образующие с ней равные углы. Докажите, что проекция O точки M равноудалена от A и B.',[114,115],vis,[('Какие углы равны по условию?','MO⊥α, поэтому OA и OB — ортогональные проекции MA и MB. В обоих прямоугольных треугольниках угол при основании наклонной острый. Поэтому условие означает ∠MAO=∠MBO=φ, где 0°<φ<90°.','first','Определение угла наклонной с плоскостью.'),('Почему два треугольника равны?','Треугольники MOA и MOB прямоугольные, у них общий катет MO и равны противолежащие этому катету острые углы. По соответствующему признаку равенства прямоугольных треугольников они равны.','second','Признак равенства по катету и противолежащему острому углу.'),('Какой вывод нужен?','Соответствующие катеты OA и OB равны. Это и означает, что O равноудалена от оснований наклонных. Для любого количества наклонных рассуждение повторяется попарно; все их основания лежат на окружности с центром O и радиусом MO/tg φ.','radii','Равенство соответствующих элементов; тангенс острого угла прямоугольного треугольника.')],'Угол наклонной с плоскостью находится при основании наклонной. Сравни два прямоугольных треугольника по общему катету и равным острым углам.',['key-task-12'])
# §13: linear angles and both worked problems.
p={'O':[0,0,0],'O1':[2,0,0],'A':[0,2,0],'B':[0,-1,math.sqrt(3)],'A1':[2,2,0],'B1':[2,-1,math.sqrt(3)],'L':[-1,0,0],'R':[3,0,0]};vis=scene(p,[['L','R'],['O','A'],['O','B'],['O1','A1'],['O1','B1']],[['L','R','A1','A'],['L','R','B1','B']],{'first':v('Первый линейный угол',[['O','A'],['O','B']]),'second':v('Второй линейный угол',[['O1','A1'],['O1','B1']])},'Два линейных угла одного двугранного угла; лучи выбраны в соответствующих полуплоскостях.')
card(13,1,'доказательство: равенство линейных углов','Почему линейный угол выбран однозначно','Докажите, что линейные углы одного двугранного угла имеют одинаковую величину независимо от выбора точки на его ребре.',[120],vis,[('Как сравнить лучи в первой грани?','Пусть O и O₁ лежат на ребре. В одной грани проведём OA и O₁A₁ перпендикулярно ребру, выбирая лучи внутри этой полуплоскости. Как перпендикуляры к одной прямой в одной плоскости они параллельны. Оба направлены в одну полуплоскость, поэтому сонаправлены.','first','Параллельность перпендикуляров в плоскости; выбор полуплоскости.'),('Что происходит во второй грани?','Аналогично OB и O₁B₁ перпендикулярны ребру и сонаправлены. Углы AOB и A₁O₁B₁ образованы соответственно сонаправленными лучами и потому равны. Для одной и той же точки O выбор направления в каждой грани уже однозначен.','second','Равенство углов с соответственно сонаправленными сторонами.'),('Почему недостаточно сказать «параллельны»?','Противоположное направление одного луча дало бы смежный угол. Здесь это исключено: каждый луч принадлежит заданной грани-полуплоскости. Поэтому величину выпуклого двугранного угла можно определить величиной любого его линейного угла.','first','Определение линейного и двугранного угла.')],'В каждой грани сравни два перпендикуляра к ребру. Отдельно объясни, почему направления лучей совпадают.',['proof-equal-linear-angles'])
p,e,f=box();vis=scene(p,e,f,{'linear':v('Линейный угол ADC',[['D','A'],['D','C']],['A','D','C'])},'Ребро DD₁ куба; грани ADD₁A₁ и CDD₁C₁.')
card(13,2,'пример: двугранный угол куба','Как найти двугранный угол куба','Найдите двугранный угол с ребром DD₁ между гранями ADD₁A₁ и CDD₁C₁ куба.',[121],vis,[('Какие лучи перпендикулярны ребру?','В квадратной грани ADD₁A₁ имеем DA⊥DD₁, а в квадратной грани CDD₁C₁ имеем DC⊥DD₁. Оба луча выходят из D и лежат в заданных полуплоскостях. Значит, ∠ADC — линейный угол искомого двугранного угла.','linear','Определение линейного угла.'),('Чему он равен?','Основание ABCD — квадрат, поэтому ∠ADC=90°. Следовательно, двугранный угол прямой. Вообще угол называют острым при величине меньше 90°, прямым при 90°, тупым между 90° и 180° и развёрнутым при 180°.','linear','Свойства квадрата; классификация выпуклых двугранных углов.'),('Как связаны четыре угла между пересекающимися плоскостями?','Любая плоскость, перпендикулярная линии пересечения, даёт две пересекающиеся прямые. Вертикальные углы равны, а смежные в сумме дают 180°. Поэтому четыре двугранных угла попарно равны; угол между плоскостями принимают равным меньшему из них. В данном кубе все четыре равны 90°.','linear','Вертикальные и смежные углы; определение угла между плоскостями.')],'Ищи два ребра куба, выходящие из D и перпендикулярные DD₁.',['embedded-example-13.6','classification-dihedral-angles','four-dihedral-angles'])
p={'A':[-8,0,0],'B':[8,0,0],'M':[0,0,0],'C':[0,6,0],'D':[0,-7.5,15*math.sqrt(3)/2]};vis=scene(p,chain(['A','B','C'])+[['A','D'],['B','D'],['C','D'],['M','C'],['M','D']],[['A','B','C'],['A','B','D']],{'altitudes':v('Высоты из C и D',[['C','M'],['D','M']]),'cosine':v('Треугольник CMD',None,['C','M','D'])},'AB=16, AC=BC=10, AD=BD=17, CD=3√39; M — середина AB.')
card(13,3,'задача 1: двугранный угол при общем основании','Двугранный угол с ребром AB равен 120°','Равнобедренные треугольники ABC и ABD имеют общее основание AB=16 см; D не принадлежит плоскости ABC. Известно DB=17 см, BC=10 см, DC=3√39 см. Найдите двугранный угол с ребром AB, грани которого содержат данные треугольники.',[122],vis,[('Как построить линейный угол?','Пусть M — середина AB. В равнобедренных треугольниках медианы DM и CM являются высотами, поэтому DM⊥AB и CM⊥AB. Следовательно, ∠CMD — линейный угол двугранного угла с гранями, содержащими C и D.','altitudes','Свойство медианы равнобедренного треугольника.'),('Как найти стороны CMD?','AM=8. По теореме Пифагора CM=√(10²−8²)=6 и DM=√(17²−8²)=15. Третья сторона CD дана: CD²=9·39=351.','cosine','Теорема Пифагора.'),('Чему равен линейный угол?','По теореме косинусов cos∠CMD=(CM²+DM²−CD²)/(2·CM·DM)=(36+225−351)/180=−1/2. Поэтому ∠CMD=120°.','cosine','Теорема косинусов.'),('Ответ и дополнительное замечание','В задаче требуется именно двугранный угол, грани которого содержат C и D, поэтому ответ — 120°. Если бы отдельно спрашивался угол между плоскостями ABC и ABD, нужно было бы взять меньший из двух смежных двугранных углов: 180°−120°=60°. Это ответ на другой вопрос, а не замена ответа данной задачи.','altitudes','Определение величины выбранного двугранного угла и отдельное определение угла между плоскостями.')],'Середина общего основания даёт две высоты. В ответе сохрани выбранные грани двугранного угла; не заменяй его автоматически меньшим углом между плоскостями.',['worked-task-13-1'])
p={'A':[0,0,0],'B':[0,4*math.sqrt(3),0],'C':[6,0,0],'M':[0,4*math.sqrt(3),4]};vis=scene(p,chain(['A','B','C'])+[['A','M'],['B','M'],['C','M']],[['A','B','C'],['A','B','M'],['A','C','M']],{'perps':v('Два перпендикуляра к AC',[['A','B'],['A','M']]),'right':v('Прямоугольный треугольник AMC',None,['A','M','C']),'angle':v('Линейный угол MAB',None,['M','A','B'])},'ABC прямоугольный при A; MB⊥(ABC), MB=4, AC=6, MC=10.')
card(13,4,'задача 2: наклонная и двугранный угол','Угол между плоскостями AMC и ABC','ABC прямоугольный при A; MB перпендикулярна плоскости ABC. При MB=4, AC=6, MC=10 найдите угол между плоскостями AMC и ABC.',[122,123],vis,[('Почему AM перпендикулярна AC?','Проекция наклонной AM на основание — AB. По условию AB⊥AC, поэтому по теореме о трёх перпендикулярах AM⊥AC. Следовательно, ∠MAB — линейный угол двугранного угла с ребром AC.','perps','Теорема 11.1.'),('Как найти AM?','В прямоугольном треугольнике AMC гипотенуза MC=10 и катет AC=6. Поэтому AM=√(100−36)=8.','right','Теорема Пифагора.'),('Чему равен угол?','MB⊥AB, поэтому в прямоугольном треугольнике ABM имеем sin∠MAB=MB/AM=4/8=1/2. Угол острый, значит, он равен 30°. Это и меньший двугранный угол между плоскостями: ответ 30°.','angle','Синус острого угла прямоугольного треугольника.')],'Сначала докажи AM⊥AC. Только после этого угол MAB можно назвать линейным.',['worked-task-13-2'])
# §14: consequences with complete proofs and a numerical common perpendicular.
p,e,f=box((4,0,0),(0,3,0),(0,0,2));vis=scene(p,e,f,{'normal':v('Ребро AA₁',[['A','A1']]),'angle':v('Линейный угол DAA₁',[['A','D'],['A','A1']])},'Прямоугольный параллелепипед: AA₁ лежит в боковой плоскости и перпендикулярно основанию.')
card(14,1,'пример: перпендикулярные грани параллелепипеда','Признак перпендикулярности в прямоугольном параллелепипеде','Объясните, почему плоскости AA₁B₁B и ABCD прямоугольного параллелепипеда перпендикулярны.',[129],vis,[('Где находится перпендикуляр к основанию?','AA₁ перпендикулярно пересекающимся прямым AB и AD плоскости основания, потому что боковые грани — прямоугольники. По признаку перпендикулярности прямой и плоскости AA₁⊥(ABCD).','normal','Теорема 8.1.'),('Как применить признак для двух плоскостей?','Плоскость AA₁B₁B содержит AA₁, перпендикулярную плоскости основания. Поэтому эти плоскости перпендикулярны. Для наглядного подтверждения линия их пересечения AB; AD и AA₁ перпендикулярны AB, а ∠DAA₁=90°.','angle','Теорема 14.1; определение линейного угла.')],'Найди в боковой грани прямую, перпендикулярную двум пересекающимся прямым основания.',['embedded-example-14.4'])
p={'O':[0,0,0],'L':[-2,0,0],'R':[2,0,0],'A':[0,0,3],'B':[0,3,0],'C':[0,-2,0],'U':[2,0,3],'V':[0,3,3]};vis=scene(p,[['L','R'],['O','A'],['O','B'],['O','C']],[['L','R','U','A'],['O','B','V','A'],['L','R','B']],{'normal':v('Перпендикуляр OA',[['O','A']]),'linear':v('Прямой линейный угол AOB',None,['A','O','B']),'planes':v('Линия пересечения двух вертикальных плоскостей',[['O','A']])},'Горизонтальная плоскость γ; вертикальные плоскости α и β. Все доказательства относятся к произвольным взаимно перпендикулярным плоскостям.')
card(14,2,'теорема 14.2 и ключевые задачи 1–2','Перпендикуляр внутри перпендикулярной плоскости','Докажите теорему 14.2 и два следствия: нормаль к γ через точку плоскости α⊥γ лежит в α; линия пересечения двух плоскостей, перпендикулярных γ, также перпендикулярна γ.',[130,131],vis,[('Как доказать теорему 14.2?','Пусть α⊥γ, их пересечение — прямая l. В α проведена AO⊥l, где O∈l. В γ проведём OB⊥l. Угол AOB — линейный угол прямого двугранного угла, поэтому AO⊥OB. Итак, AO перпендикулярна пересекающимся прямым l и OB плоскости γ; значит, AO⊥γ.','linear','Определение перпендикулярных плоскостей; признак перпендикулярности прямой и плоскости.'),('Почему нормаль через любую точку α остаётся в α?','Для точки X∈α построим внутри α прямую a через X, перпендикулярную l. Она пересекает l, в том числе в самой X, если X∈l. По только что доказанной теореме a⊥γ. Через X существует единственная прямая, перпендикулярная γ, поэтому любая такая нормаль совпадает с a и лежит в α.','normal','Теорема 14.2; единственность перпендикуляра к плоскости.'),('Почему α∩β перпендикулярна γ?','Пусть различные плоскости α и β обе перпендикулярны γ и пересекаются по c. Возьмём X∈c и проведём через X нормаль a к γ. По предыдущему следствию a лежит и в α, и в β, следовательно, a=c. Поэтому c⊥γ.','planes','Ключевая задача 1; пересечение двух различных плоскостей — прямая.')],'Для теоремы 14.2 построй второй луч линейного угла. В обоих следствиях используй единственность нормали через точку.',['theorem-14.2','key-task-14-1','key-task-14-2'])
p={'B':[0,0,0],'A':[16,0,0],'C':[-2.5,5*math.sqrt(3)/2,0],'D':[0,0,12]};a=np.array(p['A']);c=np.array(p['C']);p['E']=a+np.dot(-a,c-a)/np.dot(c-a,c-a)*(c-a);vis=scene(p,chain(['A','B','C'])+[['D',x]for x in 'ABC']+[['B','E']],[['A','B','C'],['A','B','D'],['B','C','D'],['A','C','D']],{'heights':v('Перпендикуляр BD к основанию',[['B','D']]),'base':v('Основание ABC',None,['A','B','C']),'distance':v('Общий перпендикуляр BE',[['B','E']])},'AD=20, CD=13, BD=12; боковые плоскости ABD и CBD перпендикулярны основанию; двугранный угол при BD равен 120°.')
card(14,3,'ключевая задача 3: расстояние между скрещивающимися прямыми','Расстояние между AC и BD','Плоскости ABD и CBD перпендикулярны ABC; двугранный угол с ребром BD равен 120°. При AD=20, CD=13, BD=12 найдите расстояние между AC и BD.',[131,132],vis,[('Почему BD перпендикулярна основанию?','Плоскости ABD и CBD пересекаются по BD и обе перпендикулярны плоскости ABC. По ключевой задаче 2 имеем BD⊥(ABC). Следовательно, BA и BC перпендикулярны BD, а ∠ABC — линейный угол указанного двугранного угла, то есть ∠ABC=120°.','heights','Пересечение двух плоскостей, перпендикулярных третьей.'),('Как найти стороны основания?','Треугольники ABD и CBD прямоугольные при B. Получаем AB=√(20²−12²)=16, BC=√(13²−12²)=5. Затем AC²=16²+5²−2·16·5·cos120°=361, поэтому AC=19.','base','Теоремы Пифагора и косинусов.'),('Как построить общий перпендикуляр?','В плоскости ABC опустим BE⊥AC. Так как BD⊥(ABC), то BE⊥BD. Концы BE принадлежат BD и AC, поэтому BE — их общий перпендикуляр и его длина равна расстоянию между этими прямыми.','distance','Определение общего перпендикуляра и расстояния между скрещивающимися прямыми.'),('Как вычислить BE?','Площадь ABC равна (1/2)·16·5·sin120°=20√3. С другой стороны, она равна (1/2)·AC·BE=(19/2)BE. Следовательно, BE=40√3/19.','base','Две формулы площади треугольника.')],'Сначала обоснуй BD⊥(ABC). Искомый общий перпендикуляр затем станет обычной высотой основания.',['key-task-14-3'])
